// RealWorld error responses follow the shape { errors: { <field>: [<msg>, ...] } }.
// We model them as a thrown ApiError that the Fastify error handler serializes.

export class ApiError extends Error {
  status: number;
  errors: Record<string, string[]>;

  constructor(status: number, errors: Record<string, string[]>) {
    super(`ApiError ${status}`);
    this.status = status;
    this.errors = errors;
  }
}

export const blank = (field: string) => new ApiError(422, { [field]: ["can't be blank"] });
export const taken = (field: string) => new ApiError(409, { [field]: ["has already been taken"] });
export const notFound = (field: string) => new ApiError(404, { [field]: ["not found"] });
export const forbidden = (field: string) => new ApiError(403, { [field]: ["forbidden"] });
export const missingToken = () => new ApiError(401, { token: ["is missing"] });
export const invalidToken = () => new ApiError(401, { token: ["is invalid"] });
export const invalidCredentials = () => new ApiError(401, { credentials: ["invalid"] });
export const unprocessable = (field: string, msg: string) => new ApiError(422, { [field]: [msg] });

