import jwt from "jsonwebtoken";
import type { FastifyRequest } from "fastify";
import { missingToken, invalidToken } from "./errors.js";

const SECRET = process.env.JWT_SECRET || "realworld-conduit-dev-secret-change-me";

export function signToken(userId: number): string {
  return jwt.sign({ id: userId }, SECRET, { expiresIn: "7d" });
}

// Extract "Token <jwt>" from the Authorization header. Returns the userId or null.
function readToken(req: FastifyRequest): number | null {
  const header = req.headers.authorization;
  if (!header) return null;
  const [scheme, value] = header.split(" ");
  if (scheme !== "Token" || !value) return null;
  try {
    const payload = jwt.verify(value, SECRET) as { id: number };
    return payload.id;
  } catch {
    throw invalidToken();
  }
}

// Optional auth: sets req.userId if a valid token is present, otherwise null.
export function optionalAuth(req: FastifyRequest): number | null {
  return readToken(req);
}

// Required auth: throws 401 "is missing" when no token header at all.
export function requireAuth(req: FastifyRequest): number {
  if (!req.headers.authorization) throw missingToken();
  const userId = readToken(req);
  if (userId == null) throw missingToken();
  return userId;
}

