import { prisma } from "./prisma.js";
import { signToken } from "./auth.js";

// ---- slug ----
export function makeSlug(title: string): string {
  const base = title
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  const suffix = Math.random().toString(36).slice(2, 8);
  return `${base || "article"}-${suffix}`;
}

// ---- user ----
export function userJson(user: any) {
  return {
    user: {
      email: user.email,
      username: user.username,
      bio: user.bio ?? null,
      image: user.image ?? null,
      token: signToken(user.id),
    },
  };
}

// ---- profile ----
export function profileJson(user: any, following: boolean) {
  return {
    profile: {
      username: user.username,
      bio: user.bio ?? null,
      image: user.image ?? null,
      following,
    },
  };
}

export async function isFollowing(followerId: number | null, followingId: number): Promise<boolean> {
  if (!followerId) return false;
  const rel = await prisma.follow.findUnique({
    where: { followerId_followingId: { followerId, followingId } },
  });
  return !!rel;
}

// ---- article ----
// article must be loaded with author, tags(+tag), favorites, _count of favorites.
export function articleJson(article: any, currentUserId: number | null, opts: { withBody?: boolean } = {}) {
  const withBody = opts.withBody !== false;
  const tagList = [...article.tags]
    .sort((a: any, b: any) => a.order - b.order)
    .map((t: any) => t.tag.name);
  const favorited = currentUserId
    ? article.favorites.some((f: any) => f.userId === currentUserId)
    : false;
  const following = currentUserId
    ? (article.author.followedBy || []).some((f: any) => f.followerId === currentUserId)
    : false;

  const out: any = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    tagList,
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited,
    favoritesCount: article.favorites.length,
    author: {
      username: article.author.username,
      bio: article.author.bio ?? null,
      image: article.author.image ?? null,
      following,
    },
  };
  if (withBody) out.body = article.body;
  return out;
}

export const articleInclude = {
  author: { include: { followedBy: true } },
  tags: { include: { tag: true } },
  favorites: true,
} as const;

// ---- comment ----
export function commentJson(comment: any, currentUserId: number | null) {
  const following = currentUserId
    ? (comment.author.followedBy || []).some((f: any) => f.followerId === currentUserId)
    : false;
  return {
    id: comment.id,
    createdAt: comment.createdAt.toISOString(),
    updatedAt: comment.updatedAt.toISOString(),
    body: comment.body,
    author: {
      username: comment.author.username,
      bio: comment.author.bio ?? null,
      image: comment.author.image ?? null,
      following,
    },
  };
}

export const commentInclude = {
  author: { include: { followedBy: true } },
} as const;

