import type { FastifyInstance } from "fastify";
import bcrypt from "bcryptjs";
import { prisma } from "../prisma.js";
import { requireAuth } from "../auth.js";
import { userJson } from "../views.js";
import { blank, taken, invalidCredentials, unprocessable } from "../errors.js";

const isBlank = (v: unknown): boolean => v == null || (typeof v === "string" && v.trim() === "");

export async function userRoutes(app: FastifyInstance) {
  // POST /api/users — register
  app.post("/api/users", async (req, reply) => {
    const body = (req.body as any)?.user ?? {};
    const { username, email, password } = body;

    if (isBlank(username)) throw blank("username");
    if (isBlank(email)) throw blank("email");
    if (isBlank(password)) throw blank("password");

    if (await prisma.user.findUnique({ where: { username } })) throw taken("username");
    if (await prisma.user.findUnique({ where: { email } })) throw taken("email");

    const user = await prisma.user.create({
      data: { username, email, password: await bcrypt.hash(password, 10) },
    });
    return reply.status(201).send(userJson(user));
  });

  // POST /api/users/login
  app.post("/api/users/login", async (req, reply) => {
    const body = (req.body as any)?.user ?? {};
    const { email, password } = body;

    if (isBlank(email)) throw blank("email");
    if (isBlank(password)) throw blank("password");

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !(await bcrypt.compare(password, user.password))) throw invalidCredentials();

    return reply.status(200).send(userJson(user));
  });

  // GET /api/user — current user
  app.get("/api/user", async (req, reply) => {
    const userId = requireAuth(req);
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw invalidCredentials();
    return reply.send(userJson(user));
  });

  // PUT /api/user — update current user
  app.put("/api/user", async (req, reply) => {
    const userId = requireAuth(req);
    const body = (req.body as any)?.user ?? {};
    const data: any = {};

    if ("username" in body) {
      if (isBlank(body.username)) throw blank("username");
      data.username = body.username;
    }
    if ("email" in body) {
      if (isBlank(body.email)) throw blank("email");
      data.email = body.email;
    }
    if ("password" in body) {
      if (isBlank(body.password)) throw blank("password");
      if (typeof body.password !== "string" || body.password.length < 8) {
        throw unprocessable("password", "is too short (minimum is 8 characters)");
      }
      data.password = await bcrypt.hash(body.password, 10);
    }
    // Nullable fields: empty string normalizes to null; explicit null accepted.
    if ("bio" in body) data.bio = isBlank(body.bio) ? null : body.bio;
    if ("image" in body) data.image = isBlank(body.image) ? null : body.image;

    try {
      const user = await prisma.user.update({ where: { id: userId }, data });
      return reply.send(userJson(user));
    } catch (e: any) {
      if (e?.code === "P2002") {
        const target = (e.meta?.target as string[] | string) ?? "";
        throw taken(String(target).includes("email") ? "email" : "username");
      }
      throw e;
    }
  });
}

