import { profileJson, isFollowing } from "../views.js";
import { notFound } from "../errors.js";

export async function profileRoutes(app: FastifyInstance) {
  // GET /api/profiles/:username
  app.get("/api/profiles/:username", async (req, reply) => {
    const currentUserId = optionalAuth(req);
    const { username } = req.params as { username: string };
    const user = await prisma.user.findUnique({ where: { username } });
    if (!user) throw notFound("profile");
    const following = await isFollowing(currentUserId, user.id);
    return reply.send(profileJson(user, following));
  });

  // POST /api/profiles/:username/follow
  app.post("/api/profiles/:username/follow", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { username } = req.params as { username: string };
    const target = await prisma.user.findUnique({ where: { username } });
    if (!target) throw notFound("profile");

    await prisma.follow.upsert({
      where: { followerId_followingId: { followerId: currentUserId, followingId: target.id } },
      create: { followerId: currentUserId, followingId: target.id },
      update: {},
    });
    return reply.send(profileJson(target, true));
  });

  // DELETE /api/profiles/:username/follow
  app.delete("/api/profiles/:username/follow", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { username } = req.params as { username: string };
    const target = await prisma.user.findUnique({ where: { username } });
    if (!target) throw notFound("profile");

    await prisma.follow.deleteMany({
      where: { followerId: currentUserId, followingId: target.id },
    });
    return reply.send(profileJson(target, false));
  });
}

