import type { FastifyInstance } from "fastify";
import { prisma } from "../prisma.js";
import { requireAuth, optionalAuth } from "../auth.js";
import {
  articleJson,
  articleInclude,
  commentJson,
  commentInclude,
  makeSlug,
} from "../views.js";
import { blank, notFound, forbidden, unprocessable } from "../errors.js";

const isBlank = (v: unknown): boolean => v == null || (typeof v === "string" && v.trim() === "");

function parseIntOr(v: unknown, dflt: number): number {
  const n = parseInt(String(v), 10);
  return Number.isFinite(n) && n >= 0 ? n : dflt;
}

// Replace an article's tags with the given ordered list.
async function setTags(articleId: number, tagList: string[]) {
  await prisma.articleTag.deleteMany({ where: { articleId } });
  for (let i = 0; i < tagList.length; i++) {
    const name = tagList[i];
    const tag = await prisma.tag.upsert({
      where: { name },
      create: { name },
      update: {},
    });
    await prisma.articleTag.create({ data: { articleId, tagId: tag.id, order: i } });
  }
}

async function loadArticle(slug: string) {
  return prisma.article.findUnique({ where: { slug }, include: articleInclude });
}

export async function articleRoutes(app: FastifyInstance) {
  // GET /api/articles/feed — must be registered before /:slug catch patterns are fine since exact path
  app.get("/api/articles/feed", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const q = req.query as any;
    const limit = parseIntOr(q.limit, 20);
    const offset = parseIntOr(q.offset, 0);

    const following = await prisma.follow.findMany({ where: { followerId: currentUserId } });
    const authorIds = following.map((f) => f.followingId);

    const where = { authorId: { in: authorIds } };
    const total = await prisma.article.count({ where });
    const articles = await prisma.article.findMany({
      where,
      include: articleInclude,
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      take: limit,
      skip: offset,
    });
    return reply.send({
      articles: articles.map((a) => articleJson(a, currentUserId, { withBody: false })),
      articlesCount: total,
    });
  });

  // GET /api/articles — list with filters
  app.get("/api/articles", async (req, reply) => {
    const currentUserId = optionalAuth(req);
    const q = req.query as any;
    const limit = parseIntOr(q.limit, 20);
    const offset = parseIntOr(q.offset, 0);

    const where: any = {};
    if (q.author) where.author = { username: String(q.author) };
    if (q.tag) where.tags = { some: { tag: { name: String(q.tag) } } };
    if (q.favorited) where.favorites = { some: { user: { username: String(q.favorited) } } };

    const total = await prisma.article.count({ where });
    const articles = await prisma.article.findMany({
      where,
      include: articleInclude,
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      take: limit,
      skip: offset,
    });
    return reply.send({
      articles: articles.map((a) => articleJson(a, currentUserId, { withBody: false })),
      articlesCount: total,
    });
  });

  // POST /api/articles — create
  app.post("/api/articles", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const body = (req.body as any)?.article ?? {};
    const { title, description, body: articleBody, tagList } = body;

    if (isBlank(title)) throw blank("title");
    if (isBlank(description)) throw blank("description");
    if (isBlank(articleBody)) throw blank("body");
    if (tagList != null && !Array.isArray(tagList)) throw unprocessable("tagList", "is invalid");

    const created = await prisma.article.create({
      data: { slug: makeSlug(title), title, description, body: articleBody, authorId: currentUserId },
    });
    if (Array.isArray(tagList) && tagList.length) await setTags(created.id, tagList);

    const article = await loadArticle(created.slug);
    return reply.status(201).send({ article: articleJson(article, currentUserId) });
  });

  // GET /api/articles/:slug
  app.get("/api/articles/:slug", async (req, reply) => {
    const currentUserId = optionalAuth(req);
    const { slug } = req.params as { slug: string };
    const article = await loadArticle(slug);
    if (!article) throw notFound("article");
    return reply.send({ article: articleJson(article, currentUserId) });
  });

  // PUT /api/articles/:slug
  app.put("/api/articles/:slug", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { slug } = req.params as { slug: string };
    const existing = await prisma.article.findUnique({ where: { slug } });
    if (!existing) throw notFound("article");
    if (existing.authorId !== currentUserId) throw forbidden("article");

    const body = (req.body as any)?.article ?? {};
    const data: any = {};
    if ("title" in body) {
      if (isBlank(body.title)) throw blank("title");
      data.title = body.title;
    }
    if ("description" in body) {
      if (isBlank(body.description)) throw blank("description");
      data.description = body.description;
    }
    if ("body" in body) {
      if (isBlank(body.body)) throw blank("body");
      data.body = body.body;
    }
    if ("tagList" in body) {
      if (!Array.isArray(body.tagList)) throw unprocessable("tagList", "is invalid");
    }
    // Touch updatedAt even if only tags change.
    await prisma.article.update({ where: { id: existing.id }, data: { ...data, updatedAt: new Date() } });
    if ("tagList" in body && Array.isArray(body.tagList)) await setTags(existing.id, body.tagList);

    const article = await loadArticle(slug);
    return reply.send({ article: articleJson(article, currentUserId) });
  });

  // DELETE /api/articles/:slug
  app.delete("/api/articles/:slug", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { slug } = req.params as { slug: string };
    const existing = await prisma.article.findUnique({ where: { slug } });
    if (!existing) throw notFound("article");
    if (existing.authorId !== currentUserId) throw forbidden("article");
    await prisma.article.delete({ where: { id: existing.id } });
    return reply.status(204).send();
  });

  // POST /api/articles/:slug/favorite
  app.post("/api/articles/:slug/favorite", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { slug } = req.params as { slug: string };
    const existing = await prisma.article.findUnique({ where: { slug } });
    if (!existing) throw notFound("article");
    await prisma.favorite.upsert({
      where: { userId_articleId: { userId: currentUserId, articleId: existing.id } },
      create: { userId: currentUserId, articleId: existing.id },
      update: {},
    });
    const article = await loadArticle(slug);
    return reply.send({ article: articleJson(article, currentUserId) });
  });

  // DELETE /api/articles/:slug/favorite
  app.delete("/api/articles/:slug/favorite", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { slug } = req.params as { slug: string };
    const existing = await prisma.article.findUnique({ where: { slug } });
    if (!existing) throw notFound("article");
    await prisma.favorite.deleteMany({ where: { userId: currentUserId, articleId: existing.id } });
    const article = await loadArticle(slug);
    return reply.send({ article: articleJson(article, currentUserId) });
  });

  // ---- Comments ----

  // POST /api/articles/:slug/comments
  app.post("/api/articles/:slug/comments", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { slug } = req.params as { slug: string };
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) throw notFound("article");

    const cbody = (req.body as any)?.comment?.body;
    if (isBlank(cbody)) throw blank("body");

    const comment = await prisma.comment.create({
      data: { body: cbody, articleId: article.id, authorId: currentUserId },
      include: commentInclude,
    });
    return reply.status(201).send({ comment: commentJson(comment, currentUserId) });
  });

  // GET /api/articles/:slug/comments
  app.get("/api/articles/:slug/comments", async (req, reply) => {
    const currentUserId = optionalAuth(req);
    const { slug } = req.params as { slug: string };
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) throw notFound("article");

    const comments = await prisma.comment.findMany({
      where: { articleId: article.id },
      include: commentInclude,
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    });
    return reply.send({ comments: comments.map((c) => commentJson(c, currentUserId)) });
  });

  // DELETE /api/articles/:slug/comments/:id
  app.delete("/api/articles/:slug/comments/:id", async (req, reply) => {
    const currentUserId = requireAuth(req);
    const { slug, id } = req.params as { slug: string; id: string };
    const article = await prisma.article.findUnique({ where: { slug } });
    if (!article) throw notFound("article");

    const commentId = parseInt(id, 10);
    const comment = await prisma.comment.findFirst({
      where: { id: commentId, articleId: article.id },
    });
    if (!comment) throw notFound("comment");
    if (comment.authorId !== currentUserId) throw forbidden("comment");

    await prisma.comment.delete({ where: { id: comment.id } });
    return reply.status(204).send();
  });
}

